import json

TOOL_SCHEMAS = [
    {
        "name": "get_weather",
        "description": "Get current weather for a city.",
        "parameters": {
            "type": "object",
            "properties": {
                "city": {"type": "string", "description": "City name"},
                "unit": {"type": "string", "enum": ["celsius", "fahrenheit"]}
            },
            "required": ["city"]
        }
    }
]

def get_weather(city, unit="celsius"):
    data = {"Madrid": 22, "London": 15, "Tokyo": 28}
    temp = data.get(city, 20)
    if unit == "fahrenheit":
        temp = round(temp * 9/5 + 32, 1)
    return {"city": city, "temperature": temp, "unit": unit}

simulated_call = {"name": "get_weather", "arguments": {"city": "Madrid", "unit": "celsius"}}
fn_name = simulated_call["name"]
fn_args = simulated_call["arguments"]

if fn_name == "get_weather":
    result = get_weather(**fn_args)
    print(json.dumps(result, indent=2))
